-- Insert in dependency order: career_paths -> roles -> competencies.
INSERT INTO public.career_paths (id, name, description, created_at)
VALUES
  (1, E'360 Career Path', E'The full 360° recruitment career track. Manage the full recruitment lifecycle from client development through to placement. Click to view the full career path diagram.', E'2026-04-16T14:30:07.063937'),
  (2, E'180 Career Path', E'The 180° delivery recruitment track. Specialist recruiters focused on candidate sourcing, delivery and talent placement. Click to view the full career path diagram.', E'2026-04-16T14:30:07.108624')
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  created_at = EXCLUDED.created_at;

INSERT INTO public.roles (id, career_path_id, title, level, job_spec, created_at)
VALUES
  (55, 1, E'Recruitment Consultant Contract', 1, E'\n\nRecruitment Consultant 360 – Contract\n\n\n\n\n\nPurpose Of The Role\n\n\n\nTo generate revenue through contract placements within a defined market.\n\n\n\nThe Recruitment Consultant is responsible for developing client relationships, sourcing and managing contractors, and delivering successful placements. The role focuses on building a strong contractor network, maintaining consistent pipeline and generating recurring revenue through contractor placements and extensions.\n\n\n\n\n\nRole Responsibilities\n\n\n\nClient Development\n\n• Identify and develop new client relationships within your defined contract market\n\n• Arrange and attend client qualification meetings\n\n• Build long-term relationships that generate repeat contract hiring\n\n\n\nContractor Management\n\n• Source and qualify contractors through multiple channels\n\n• Build talent pools and maintain an active contractor network\n\n• Maintain strong relationships with contractors throughout assignments\n\n• Manage onboarding, extensions and redeployment opportunities\n\n\n\nRecruitment Delivery\n\n• Execute the contract recruitment process from qualification through to placement\n\n• Manage interview processes between clients and contractors\n\n• Prepare CVs to agreed company standards\n\n• Maintain strong communication with all parties throughout the process\n\n\n\nMarket Knowledge\n\n• Develop strong understanding of contractor rates and market trends\n\n• Stay informed on competitor activity and hiring demand\n\n• Position yourself as a credible specialist within your niche\n\n\n\nOperational Standards\n\n• Maintain accurate records within Bullhorn / CRM\n\n• Record all conversations and actions with candidates and clients\n\n• Follow company recruitment and compliance processes\n\n\n\n\n\nWhat Success Looks Like – How The Role Is Measured\n\n\n\nFinancial Performance\n\n• Achieving or exceeding revenue targets\n\n• Generating consistent monthly contractor GP\n\n\n\nPipeline & Business Development\n\n• Maintaining a healthy pipeline of contract opportunities\n\n• Building a strong contractor network within your niche\n\n• Generating repeat business from existing clients\n\n\n\nActivity & Delivery\n\n• Achieving weekly activity standards\n\n• Consistently sourcing and qualifying contractors\n\n• Progressing interviews and placements through the pipeline\n\n\n\nCustomer Experience\n\n• Delivering a high-quality experience to both contractors and clients\n\n• Building trust and long-term working relationships\n\n\n\nProfessional Standards\n\n• Maintaining accurate CRM records\n\n• Following recruitment and compliance processes consistently\n\n• Demonstrating reliability and professionalism\n\n\n\n\n\nBehaviours & Values Expected In This Role\n\n\n\nConsultant level are expected to demonstrate:\n\n\n\nAccountability – owning activity, pipeline and revenue generation\n\nCoachability – continuing to develop capability through feedback and learning\n\nResilience – maintaining consistent performance through rejection and setbacks\n\nCommercial Awareness – understanding the financial impact of recruitment decisions\n\nProfessional Conduct – maintaining strong standards with clients, candidates and colleagues\n\n\n\nThese behaviours form part of probation and promotion assessments.\n\nRecruitment Consultants are also expected to consistently demonstrate our 6 DNA values:\n\nDriven\nHow much do you want to achieve your goals?\n\nDisciplined\nConsistently performing the small actions required to achieve your goals.\n\nCompetitive\nSelf-motivated and driven to continually achieve your best.\n\nPositive\nMaintaining a solutions-focused attitude.\n\nResilient\nBouncing back quickly from setbacks.\n\nCommitted\nShowing dedication to achieving your goals and contributing to team success.\n\nAt Consultant level these values are demonstrated through personal performance, activity discipline and accountability for revenue generation.\n\n\n\n\n\n', E'2026-04-17T10:04:54.088555'),
  (56, 1, E'Recruitment Consultant Perm', 2, E'\n\nRecruitment Consultant 360 – Permanent\n\n\n\n\n\nPurpose Of The Role\n\n\n\nTo generate revenue through full-cycle permanent recruitment within a defined niche.\n\n\n\nThe Recruitment Consultant is responsible for building and developing client relationships, sourcing and managing candidates and delivering successful placements. The role focuses on creating consistent pipeline, strong candidate control and predictable billing performance.\n\n\n\n\n\nRole Responsibilities\n\n\n\nClient Development\n\n• Identify and develop new client relationships within your defined market\n\n• Build a pipeline of potential clients within your niche\n\n• Arrange and attend client qualification meetings\n\n• Develop long-term relationships that generate repeat business\n\n\n\nCandidate Management\n\n• Source and qualify relevant candidates through multiple channels\n\n• Build talent pools and maintain active candidate networks\n\n• Prepare candidates effectively for interviews\n\n• Manage candidate communication throughout the recruitment process\n\n\n\nRecruitment Delivery\n\n• Fully execute the recruitment lifecycle from qualification through to placement\n\n• Prepare CVs to agreed company standards\n\n• Manage interview processes between candidates and clients\n\n• Maintain strong communication with all parties throughout the process\n\n\n\nMarket Knowledge\n\n• Develop strong knowledge of your sector and hiring market\n\n• Build personal credibility with both clients and candidates\n\n• Stay informed on competitor activity, salary levels and hiring trends\n\n\n\nOperational Standards\n\n• Maintain accurate records within Bullhorn / CRM\n\n• Record all candidate and client conversations properly\n\n• Follow company recruitment processes and compliance requirements\n\n\n\n\n\nWhat Success Looks Like – How The Role Is Measured\n\n\n\nFinancial Performance\n\n• Achieving or exceeding annual and monthly revenue targets\n\n• Maintaining consistent billing performance\n\n\n\nPipeline & Business Development\n\n• Maintaining sufficient live opportunities to support revenue delivery\n\n• Building a pipeline of clients and candidates within your niche\n\n• Generating new business and repeat client relationships\n\n\n\nActivity & Delivery\n\n• Achieving weekly activity standards\n\n• Maintaining consistent sourcing and outreach activity\n\n• Progressing interviews and placements through the pipeline\n\n\n\nCustomer Experience\n\n• Delivering a high-quality experience to both candidates and clients\n\n• Generating positive testimonials, referrals or repeat work\n\n\n\nProfessional Standards\n\n• Maintaining accurate CRM records\n\n• Following recruitment processes consistently\n\n• Demonstrating reliability and professionalism\n\n\n\n\n\nBehaviours & Values Expected In This Role\n\n\n\nConsultant level are expected to demonstrate:\n\n\n\nAccountability – owning activity, pipeline and revenue generation\n\nCoachability – continuing to develop capability through feedback and learning\n\nResilience – maintaining consistent performance through rejection and setbacks\n\nCommercial Awareness – understanding the financial impact of recruitment decisions\n\nProfessional Conduct – maintaining strong standards with clients, candidates and colleagues\n\n\n\nThese behaviours form part of probation and promotion assessments.\n\n\n\nConsultants are also expected to consistently demonstrate our 6 DNA values:\n\n\n\nDriven  \n\nHow much do you want to achieve your goals?\n\n\n\nDisciplined  \n\nConsistently performing the small actions required to achieve your goals.\n\n\n\nCompetitive  \n\nSelf-motivated and driven to continually achieve your best.\n\n\n\nPositive  \n\nMaintaining a solutions-focused attitude.\n\n\n\nResilient  \n\nBouncing back quickly from setbacks.\n\n\n\nCommitted  \n\nShowing dedication to achieving your goals and contributing to team success.\n\n\n\nAt Consultant level these values are demonstrated through personal performance, activity discipline and accountability for revenue generation.\n\n\n\n\n\n\n\n', E'2026-04-17T10:04:54.088555'),
  (57, 1, E'Senior Recruitment Consultant Contract', 3, E'\n\nSenior Recruitment Consultant 360 – Contract\n\n\n\n\n\nPurpose Of The Role\n\n\n\nTo deliver consistent recurring revenue through contractor placements while demonstrating strong market expertise and client influence.\n\n\n\nSenior Recruitment Consultants operate with full ownership of their contractor network and client relationships, building stable contractor books and generating repeat contract business.\n\n\n\n\n\nRole Responsibilities\n\n\n\nClient Development\n\n• Develop and maintain strong client relationships within your niche\n\n• Identify opportunities for repeat contract hiring\n\n• Influence hiring decisions and rate negotiations\n\n\n\nContractor Management\n\n• Build and maintain strong contractor networks\n\n• Manage contractor relationships throughout assignments\n\n• Proactively manage extensions and redeployment opportunities\n\n\n\nRecruitment Delivery\n\n• Execute the contract recruitment lifecycle from qualification through to placement\n\n• Manage onboarding and compliance requirements\n\n• Maintain clear communication between clients and contractors\n\n\n\nMarket Expertise\n\n• Demonstrate strong knowledge of contractor markets and rate expectations\n\n• Position yourself as a trusted specialist within your niche\n\n\n\nOperational Standards\n\n• Maintain accurate CRM records\n\n• Follow recruitment and compliance processes\n\n• Manage contractor information and documentation properly\n\n\n\n\n\nWhat Success Looks Like – How The Role Is Measured\n\n\n\nFinancial Performance\n\n• Achieving or exceeding Senior contract revenue targets\n\n• Maintaining consistent monthly contractor GP\n\n\n\nPipeline & Business Development\n\n• Maintaining a strong contractor network\n\n• Building repeat business with existing clients\n\n• Generating new contract opportunities within your market\n\n\n\nActivity & Delivery\n\n• Maintaining strong sourcing and qualification activity\n\n• Progressing contractor placements through the pipeline\n\n• Delivering strong conversion from interviews to placements\n\n\n\nCustomer Experience\n\n• Building trusted relationships with clients and contractors\n\n• Delivering a reliable and professional recruitment process\n\n\n\nProfessional Standards\n\n• Operating independently and responsibly\n\n• Maintaining accurate CRM and compliance records\n\n• Managing contractor processes efficiently\n\n\n\n\n\nBehaviours & Values Expected In This Role\n\n\n\nSenior level are expected to demonstrate:\n\n\n\nOwnership – taking full responsibility for the performance and management of your desk\n\nCommercial Thinking – understanding margin, value and the commercial impact of recruitment decisions\n\nInfluence – confidently managing client and candidate expectations\n\nResilience – maintaining consistent performance through market fluctuations and pressure\n\nProfessional Leadership – setting standards for others through behaviour and professionalism\n\n\n\nThese behaviours form part of probation and promotion assessments.\n\n\n\nAssociates are also expected to consistently demonstrate our 6 DNA values:\n\n\n\nDriven  \n\nHow much do you want to achieve your goals?\n\n\n\nDisciplined  \n\nConsistently performing the small actions required to achieve your goals.\n\n\n\nCompetitive  \n\nSelf-motivated and driven to continually achieve your best.\n\n\n\nPositive  \n\nMaintaining a solutions-focused attitude.\n\n\n\nResilient  \n\nBouncing back quickly from setbacks.\n\n\n\nCommitted  \n\nShowing dedication to achieving your goals and contributing to team success.\n\n\n\nAt Senior level these values are demonstrated through ownership of desk performance, strong commercial discipline and setting a positive example within the team.\n\n\n\n\n\n\n\n', E'2026-04-17T10:04:54.088555'),
  (58, 1, E'Senior Recruitment Consultant Perm', 4, E'\n\nSenior Recruitment Consultant 360 – Permanent\n\n\n\n\n\nPurpose Of The Role\n\n\n\nTo deliver consistent revenue performance through full-cycle permanent recruitment while demonstrating strong client influence and ownership of a specialist market.\n\n\n\nSenior Recruitment Consultants operate with increased autonomy and accountability, managing their desk strategically and generating repeat business through trusted client relationships.\n\n\n\n\n\nRole Responsibilities\n\n\n\nClient Development\n\n• Develop and grow relationships with key clients within your niche\n\n• Identify opportunities for repeat and expanded business\n\n• Influence hiring decisions and recruitment processes\n\n\n\nCandidate Management\n\n• Build and maintain strong networks of high-quality candidates\n\n• Manage complex recruitment processes confidently\n\n• Provide candidates with clear preparation and guidance throughout the process\n\n\n\nRecruitment Delivery\n\n• Execute the recruitment lifecycle from qualification through to placement\n\n• Manage multiple active roles and processes simultaneously\n\n• Maintain high-quality communication with clients and candidates\n\n\n\nMarket Expertise\n\n• Demonstrate strong knowledge of your sector and hiring trends\n\n• Build a reputation as a credible market specialist\n\n• Develop insights that help clients make informed hiring decisions\n\n\n\nOperational Standards\n\n• Maintain high-quality CRM records\n\n• Follow recruitment processes and compliance standards\n\n• Support junior consultants where appropriate\n\n\n\n\n\nWhat Success Looks Like – How The Role Is Measured\n\n\n\nFinancial Performance\n\n• Achieving or exceeding Senior revenue targets\n\n• Maintaining consistent billing performance across quarters\n\n\n\nPipeline & Business Development\n\n• Maintaining strong forward pipeline within your niche\n\n• Generating repeat business from established clients\n\n• Expanding relationships within existing client accounts\n\n\n\nActivity & Delivery\n\n• Maintaining high-quality recruitment activity\n\n• Consistently progressing roles and placements\n\n• Delivering strong conversion from interviews to placements\n\n\n\nCustomer Experience\n\n• Delivering a high-quality experience to clients and candidates\n\n• Generating repeat business and positive feedback\n\n\n\nProfessional Standards\n\n• Operating independently and reliably\n\n• Maintaining accurate CRM records and recruitment documentation\n\n• Demonstrating strong personal organisation and desk management\n\n\n\n\n\n\n\nBehaviours & Values Expected In This Role\n\n\n\nSenior level are expected to demonstrate:\n\n\n\nOwnership – taking full responsibility for the performance and management of your desk\n\nCommercial Thinking – understanding margin, value and the commercial impact of recruitment decisions\n\nInfluence – confidently managing client and candidate expectations\n\nResilience – maintaining consistent performance through market fluctuations and pressure\n\nProfessional Leadership – setting standards for others through behaviour and professionalism\n\n\n\nThese behaviours form part of probation and promotion assessments.\n\n\n\nSeniors are also expected to consistently demonstrate our 6 DNA values:\n\n\n\nDriven  \n\nHow much do you want to achieve your goals?\n\n\n\nDisciplined  \n\nConsistently performing the small actions required to achieve your goals.\n\n\n\nCompetitive  \n\nSelf-motivated and driven to continually achieve your best.\n\n\n\nPositive  \n\nMaintaining a solutions-focused attitude.\n\n\n\nResilient  \n\nBouncing back quickly from setbacks.\n\n\n\nCommitted  \n\nShowing dedication to achieving your goals and contributing to team success.\n\n\n\nAt Senior level these values are demonstrated through ownership of desk performance, strong commercial discipline and setting a positive example within the team.\n\n\n\n\n\n', E'2026-04-17T10:04:54.088555'),
  (59, 1, E'Principal Consultant Contract', 5, E'\n\nPrincipal Recruitment Consultant 360 – Contract\n\n\n\n\n\nPurpose Of The Role\n\n\n\nThe Principal Recruitment Consultant is responsible for delivering high levels of recurring contract revenue while operating as a trusted specialist within their market.\n\n\n\nPrincipals build stable contractor books, manage strategic client relationships and generate consistent revenue through strong commercial discipline and market expertise.\n\n\n\n\n\nRole Responsibilities\n\n\n\nClient Development & Account Ownership\n\n• Build and develop long-term client relationships within your contract market\n\n• Expand opportunities within existing client accounts\n\n• Influence hiring decisions and rate negotiations\n\n• Position yourself as a trusted recruitment partner\n\n\n\nContractor Network Development\n\n• Build and maintain strong contractor networks\n\n• Maintain clear visibility of contractor availability and market demand\n\n• Develop repeat contractor engagement and retention\n\n\n\nRecruitment Delivery\n\n• Manage the full contract recruitment lifecycle\n\n• Run multiple contract processes simultaneously\n\n• Manage onboarding, compliance and contractor engagement\n\n\n\nMarket Leadership\n\n• Demonstrate strong knowledge of contractor markets and rate expectations\n\n• Build credibility as a trusted specialist within your niche\n\n• Provide insight to clients on contractor availability and hiring trends\n\n\n\nOperational Standards\n\n• Maintain accurate CRM records\n\n• Follow recruitment and compliance processes\n\n• Manage contractor documentation and processes effectively\n\n\n\n\n\n\n\n\n\nWhat Success Looks Like – How The Role Is Measured\n\n\n\nFinancial Performance\n\n• Achieving or exceeding contract revenue targets\n\n• Maintaining strong contractor GP generation\n\n• Delivering consistent recurring revenue across quarters\n\n\n\nPipeline & Business Development\n\n• Maintaining a strong contractor network\n\n• Building repeat contract business with existing clients\n\n• Expanding opportunities within established accounts\n\n\n\nActivity & Delivery\n\n• Maintaining strong sourcing and qualification activity\n\n• Managing contractor pipelines effectively\n\n• Delivering strong conversion from interview to placement\n\n\n\nCustomer Experience\n\n• Building trusted relationships with clients and contractors\n\n• Delivering a reliable and professional recruitment process\n\n\n\nProfessional Standards\n\n• Operating independently and responsibly\n\n• Maintaining accurate CRM and compliance records\n\n• Managing contractor processes efficiently\n\n\n\n\n\nBehaviours & Values Expected In This Role\n\n\n\nPrincipal level expected to demonstrate:\n\n\n\nStrategic Ownership – full accountability for desk performance and client relationships\n\nCommercial Expertise – strong understanding of margins, rates and deal structure\n\nInfluence & Authority – acting as a trusted advisor to clients and contractors\n\nRole Modelling – setting professional and behavioural standards\n\nConsistency – delivering reliable performance and high standards over time\n\n\n\nThese behaviours form part of probation and promotion assessments.\n\n\n\nPrincipals are also expected to consistently demonstrate our 6 DNA values:\n\n\n\n\n\nDriven  \n\nHow much do you want to achieve your goals?\n\n\n\nDisciplined  \n\nConsistently performing the small actions required to achieve your goals.\n\n\n\nCompetitive  \n\nSelf-motivated and driven to continually achieve your best.\n\n\n\nPositive  \n\nMaintaining a solutions-focused attitude.\n\n\n\nResilient  \n\nBouncing back quickly from setbacks.\n\n\n\nCommitted  \n\nShowing dedication to achieving your goals and contributing to team success.\n\n\n\nAt Principal level these values are demonstrated through market leadership, consistent high performance and influencing standards across the business.\n\n\n\n\n\n', E'2026-04-17T10:04:54.088555'),
  (60, 1, E'Principal Consultant Perm', 6, E'\n\nPrincipal Recruitment Consultant 360 – Permanent\n\n\n\n\n\nPurpose Of The Role\n\n\n\nThe Principal Recruitment Consultant is a senior billing specialist responsible for delivering high levels of revenue through strategic client relationships and deep market expertise.\n\n\n\nPrincipals operate as trusted advisors within their niche, generating repeat business and managing complex recruitment processes while maintaining strong commercial discipline and consistent billing performance.\n\n\n\n\n\nRole Responsibilities\n\n\n\nClient Development & Account Ownership\n\n• Build and develop long-term relationships with key clients within your market\n\n• Expand opportunities within existing client accounts\n\n• Influence hiring decisions and recruitment strategies\n\n• Position yourself as a trusted recruitment partner\n\n\n\nCandidate Network Development\n\n• Build and maintain strong networks of high-quality candidates\n\n• Maintain deep knowledge of candidate availability and market movement\n\n• Manage complex candidate processes including counter-offers and competing opportunities\n\n\n\nRecruitment Delivery\n\n• Manage the full recruitment lifecycle from qualification through to placement\n\n• Run complex recruitment processes across multiple clients and roles\n\n• Deliver consistent high-value placements\n\n\n\nMarket Leadership\n\n• Demonstrate strong sector knowledge and hiring trends\n\n• Build a reputation as a market expert within your niche\n\n• Develop insights that help clients make better hiring decisions\n\n\n\nOperational Standards\n\n• Maintain high-quality CRM records\n\n• Follow recruitment processes and compliance requirements\n\n• Support team members through knowledge sharing and informal guidance\n\n\n\n\n\n\n\nWhat Success Looks Like – How The Role Is Measured\n\n\n\nFinancial Performance\n\n• Achieving or exceeding Principal revenue targets\n\n• Delivering consistent billing across quarters\n\n• Generating high-value placements\n\n\n\nPipeline & Business Development\n\n• Maintaining strong forward pipeline across multiple clients\n\n• Generating repeat business and expanding client accounts\n\n• Building long-term strategic client relationships\n\n\n\nActivity & Delivery\n\n• Maintaining high-quality recruitment activity\n\n• Managing multiple recruitment processes effectively\n\n• Delivering strong conversion rates from interview to placement\n\n\n\nCustomer Experience\n\n• Delivering a trusted advisory experience to clients and candidates\n\n• Generating referrals, repeat work and positive feedback\n\n\n\nProfessional Standards\n\n• Operating with high levels of independence and accountability\n\n• Maintaining accurate CRM records and recruitment documentation\n\n• Demonstrating excellent organisation and desk management\n\n\n\n\n\nBehaviours & Values Expected In This Role\n\n\n\nPrincipal level are expected to demonstrate: \n\n\n\nStrategic Ownership – operating with full accountability for desk performance and client relationships\n\nCommercial Leadership – demonstrating strong understanding of margin, deal structure and long-term account value\n\nInfluence & Authority – acting as a trusted advisor to clients and candidates\n\nResilience – sustaining high performance through complex or competitive processes\n\nRole Modelling – consistently setting behavioural and professional standards across the business\n\n\n\nThese behaviours form part of probation and promotion assessments.\n\n\n\nPrincipals are also expected to consistently demonstrate our 6 DNA values:\n\n\n\n\n\nDriven  \n\nHow much do you want to achieve your goals?\n\n\n\nDisciplined  \n\nConsistently performing the small actions required to achieve your goals.\n\n\n\nCompetitive  \n\nSelf-motivated and driven to continually achieve your best.\n\n\n\nPositive  \n\nMaintaining a solutions-focused attitude.\n\n\n\nResilient  \n\nBouncing back quickly from setbacks.\n\n\n\nCommitted  \n\nShowing dedication to achieving your goals and contributing to team success.\n\n\n\nAt Principal level these values are demonstrated through market leadership, consistent high performance and influencing standards across the business.\n\n\n\n\n\n', E'2026-04-17T10:04:54.088555'),
  (61, 1, E'Sector Lead Contract', 7, E'\n\nSector Lead – Contract\n\n\n\n\n\nPurpose Of The Role\n\n\n\nThe Sector Lead is responsible for driving the performance, development and commercial success of a defined contract recruitment sector while maintaining strong personal billing performance.\n\n\n\nSector Leads lead by example through consistent personal delivery, supporting consultants to improve performance and ensuring strong contractor pipeline, activity and revenue standards across the sector.\n\n\n\n\n\nRole Responsibilities\n\n\n\nSector Performance & Leadership\n\n• Drive performance across the contract sector through leading by example, coaching and accountability\n\n• Ensure consultants maintain strong contractor activity levels, pipeline management and recruitment standards\n\n• Support consultants with deal strategy, client development and contract recruitment processes\n\n• Provide regular feedback and development guidance to consultants within the sector\n\n\n\nClient Development & Market Ownership\n\n• Develop strategic client relationships within the contract sector\n\n• Expand opportunities within existing client accounts and generate new business\n\n• Position the business as a specialist contract recruitment provider within the market\n\n\n\nContractor Network Development\n\n• Build and maintain strong contractor networks within the sector\n\n• Support consultants in developing and managing contractor relationships\n\n• Maintain visibility of contractor availability and market demand\n\n\n\nRecruitment Delivery\n\n• Maintain strong personal contract revenue performance\n\n• Support consultants with complex contract recruitment processes\n\n• Ensure high-quality delivery across all client and contractor interactions\n\n\n\nConsultant Development & Support\n\n• Support onboarding and development of new consultants\n\n• Share contract market knowledge, best practice and recruitment techniques\n\n• Help raise capability and standards across the sector\n\n\n\nOperational Standards\n\n• Maintain accurate CRM records and reporting across the sector\n\n• Ensure recruitment processes and compliance standards are followed\n\n• Maintain visibility of sector contractor pipeline, activity and revenue performance\n\n\n\n\n\nWhat Success Looks Like – How The Role Is Measured\n\n\n\nFinancial Performance\n\n• Achieving or exceeding personal contract revenue targets\n\n• Contributing to the overall contract revenue performance of the sector\n\n• Supporting consistent contractor GP generation across the sector\n\n\n\nSector Growth & Pipeline\n\n• Developing strong client relationships across the contract market\n\n• Expanding opportunities within existing client accounts\n\n• Maintaining strong contractor pipeline visibility and forecasting\n\n\n\nConsultant Performance\n\n• Supporting consultants to improve contract recruitment capability\n\n• Driving activity standards and recruitment discipline across the sector\n\n• Contributing to improved contract revenue performance across the sector\n\n\n\nCustomer Experience\n\n• Maintaining strong relationships with clients and contractors\n\n• Ensuring high-quality contract recruitment delivery across the sector\n\n\n\nProfessional Standards\n\n• Maintaining accurate CRM records and reporting\n\n• Ensuring recruitment processes and compliance standards are followed\n\n• Operating with strong organisation, communication and professionalism\n\n\n\n\n\n\n\nBehaviours & Values Expected In This Role\n\n\n\nSector Leads are expected to demonstrate:\n\n\n\nSector Leadership – driving standards and performance across the sector through influence, expertise and example\n\nCommercial Ownership – understanding and driving contract revenue performance across the sector\n\nInfluence & Coaching – supporting consultants to improve capability and performance\n\nResilience – maintaining momentum through challenges and market fluctuations\n\nRole Modelling – consistently demonstrating the behaviours and standards expected across the sector\n\n\n\nThese behaviours form part of probation and promotion assessments.\n\n\n\nSector Leads are also expected to consistently demonstrate our 6 DNA values:\n\n\n\nDriven  \n\nHow much do you want to achieve your goals?\n\n\n\nDisciplined  \n\nConsistently performing the small actions required to achieve your goals.\n\n\n\nCompetitive  \n\nSelf-motivated and driven to continually achieve your best.\n\n\n\nPositive  \n\nMaintaining a solutions-focused attitude.\n\n\n\nResilient  \n\nBouncing back quickly from setbacks.\n\n\n\nCommitted  \n\nShowing dedication to achieving your goals and contributing to team success.\n\n\n\nAt Sector Lead level these values are demonstrated through leadership, accountability for sector performance and consistently raising standards across the contract market.\n\n\n\n\n\n', E'2026-04-17T10:04:54.088555'),
