COMMIT;
-- Career-path reference-data extract from Development.
-- Scope: only 180 Career Path and 360 Career Path, plus their roles and competencies.
-- This script does not include users, assessments, progress, learning, probation,
-- financial, authentication, password, evidence, or other demo/test records.
-- It is intentionally not executed by this export.

BEGIN;

-- Fail safely if an existing ID belongs to a different reference record.
DO $guard$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.career_paths existing
    JOIN (VALUES
      (1, E'360 Career Path'),
  (2, E'180 Career Path')
    ) AS incoming(id, name) ON incoming.id = existing.id
    WHERE existing.name IS DISTINCT FROM incoming.name
  ) THEN
    RAISE EXCEPTION 'Career-path ID collision: an existing ID has a different name';
  END IF;

  IF EXISTS (
    WITH incoming(id, career_path_id, title, level) AS (VALUES
      (55, 1, E'Recruitment Consultant Contract', 1),
  (56, 1, E'Recruitment Consultant Perm', 2),
  (57, 1, E'Senior Recruitment Consultant Contract', 3),
  (58, 1, E'Senior Recruitment Consultant Perm', 4),
  (59, 1, E'Principal Consultant Contract', 5),
  (60, 1, E'Principal Consultant Perm', 6),
  (61, 1, E'Sector Lead Contract', 7),
  (62, 1, E'Sector Lead Perm', 8),
  (63, 1, E'Team Leader Contract', 9),
  (64, 1, E'Team Leader Perm', 10),
  (65, 1, E'Divisional Manager Contract', 11),
  (66, 1, E'Divisional Manager Perm', 12),
  (67, 1, E'Associate Director Contract', 13),
  (68, 1, E'Associate Director Perm', 14),
  (41, 2, E'Recruitment Consultant Perm', 1),
  (42, 2, E'Recruitment Consultant Contract', 2),
  (43, 2, E'Senior Recruitment Consultant Perm', 3),
  (44, 2, E'Senior Recruitment Consultant Contract', 4),
  (45, 2, E'Principal Consultant Perm', 5),
  (46, 2, E'Principal Consultant Contract', 6),
  (47, 2, E'Sector Lead Perm', 7),
  (48, 2, E'Sector Lead Contract', 8),
  (49, 2, E'Team Leader Perm', 9),
  (50, 2, E'Team Leader Contract', 10),
  (51, 2, E'Divisional Manager Perm', 11),
  (52, 2, E'Divisional Manager Contract', 12),
  (53, 2, E'Associate Director Perm', 13),
  (54, 2, E'Associate Director Contract', 14)
    )
    SELECT 1
    FROM incoming
    JOIN public.roles existing ON existing.id = incoming.id
    WHERE (existing.career_path_id, existing.title, existing.level)
          IS DISTINCT FROM (incoming.career_path_id, incoming.title, incoming.level)
  ) THEN
    RAISE EXCEPTION 'Role ID collision: an existing ID has different reference identity';
  END IF;

  IF EXISTS (
    WITH incoming(id, role_id, name, category) AS (VALUES
      (715, 41, E'Recruitment Consultant 180 (Delivery)', E'Core Competencies'),
  (716, 41, E'Accountability', E'Core Competencies'),
