  (52, 2, E'Divisional Manager Contract', 12),
  (53, 2, E'Associate Director Perm', 13),
  (54, 2, E'Associate Director Contract', 14)
    )
    SELECT 1
    FROM incoming
    JOIN public.roles existing ON existing.id = incoming.id
    WHERE (existing.career_path_id, existing.title, existing.level)
          IS DISTINCT FROM (incoming.career_path_id, incoming.title, incoming.level)
